var t=`0517-kleicha`;var i=`world-0517`;var o=`IQ`;var a=`western-asia`;var r=8;var s=68;var u={en:`Kleicha`,ua:`Клейча`};var d={en:`A traditional dish from Iraq, centered on all-purpose flour, date paste. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Ірак. Основні складники: пшеничне борошно універсальне, фінікова паста. Домашній варіант із кількостями продуктів за етапами приготування.`};var g=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 16 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 16 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:16,i:[[`all-purpose-flour`,380,`g`],[`unsalted-butter`,150,`g`],[`water`,140,`ml`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:9,i:[[`date-paste`,300,`g`],[`ground-cardamom`,5,`g`],[`ground-cinnamon`,3,`g`]]},{en:`Divide and shape the dough as required. Place on a lined tray and proof for about 18 minutes while the oven heats.`,ua:`Поділіть і сформуйте тісто відповідно до виробу. Викладіть на деко з пергаментом і залиште підходити приблизно на 18 хвилин, поки гріється духовка.`,t:[`pre-shaping-dough`,`final-proofing`],m:18,i:[]},{en:`Bake in a preheated 180°C oven for about 25 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 25 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:25,i:[]}];var l={slug:t,id:i,country:`IQ`,region:a,servings:8,minutes:68,title:u,text:d,steps:g};export{o as country,l as default,i as id,s as minutes,a as region,r as servings,t as slug,g as steps,d as text,u as title};